import React, { useRef } from 'react';
import { useKeyboardShortcuts } from '@fiverr-private/hooks';
import { TimesButton } from '@fiverr-private/button';
import { usePopoverContext } from '../PopoverContext';
import type { PopoverCloseIconProps } from '../types';

const PopoverCloseIcon = ({
  dataTestId,
  dataTrackTag = 'popover_close_icon',
  dataTrackValue,
}: PopoverCloseIconProps) => {
  const { setOpen } = usePopoverContext();
  const ref = useRef(null);
  useKeyboardShortcuts([
    {
      trigger: 'enter',
      handler: () => {
        if (document.activeElement === ref.current) {
          setOpen(false);
        }
      },
    },
  ]);

  return (
    <TimesButton
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
      size="3xs"
      dataTestId={dataTestId}
      ref={ref}
      onClick={() => setOpen(false)}
    />
  );
};

PopoverCloseIcon.displayName = 'PopoverCloseIcon';

export default PopoverCloseIcon;
