import React from 'react';
import { LazyComponent } from '@fiverr-private/ui_utils';
import { usePopoverContext } from '../PopoverContext';
import type { PopoverLazyContentProps } from '../types';

const PopoverLazyContent = (props: PopoverLazyContentProps) => {
  const { open } = usePopoverContext();

  return <LazyComponent shouldImport={open} {...props} />;
};

export default PopoverLazyContent;
